<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {typeDeviceUuid} from '../device-types/type-devices-api'
import {iccidInformationTransport,prepareIccidInformation,iccidInformationMatches,type IccidInformation,type IccidInformationIntent,type IccidInformationTransport} from '../device-types/iccid-information-api'
const props=withDefaults(defineProps<{deviceId:string;disabled?:boolean;reference?:boolean;transport?:IccidInformationTransport}>(),{disabled:false,transport:()=>iccidInformationTransport})
const emit=defineEmits<{locked:[value:boolean];changed:[]}>(),roles=['OWNER','ADMIN','OPERATOR','VIEWER']
const denied=ref(false),readable=computed(()=>!denied.value&&session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.deviceId)&&can('device:read')&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||'')),writable=computed(()=>readable.value&&can('device:update')&&currentProject.value?.status==='ACTIVE'&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const value=shallowRef<IccidInformation>(),snapshot=shallowRef<IccidInformation>(),intent=shallowRef<IccidInformationIntent>(),observed=shallowRef<IccidInformation>(),review=ref<'unknown'|'rejected'>(),shown=ref(false),busy=ref(false),draft=ref(''),error=ref(''),notice=ref(''),locked=computed(()=>shown.value||busy.value||!!review.value)
let generation=0,alive=true,controller:AbortController|undefined
function clear(){generation++;controller?.abort();value.value=undefined;snapshot.value=undefined;intent.value=undefined;observed.value=undefined;review.value=undefined;shown.value=false;busy.value=false;draft.value='';error.value='';notice.value=''}
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,device:props.deviceId,actor:session.user?.accountId}}
function current(s:ReturnType<typeof capture>){return alive&&readable.value&&s.generation===generation&&s.epoch===identityEpoch()&&s.project===projectId.value&&s.device===props.deviceId&&s.actor===session.user?.accountId}
async function load(recover=false){if(!readable.value||busy.value||review.value&&!recover)return;const s=capture();busy.value=true;error.value='';controller=new AbortController();try{const actual=await props.transport.read(s.project,s.device,controller.signal);if(!current(s))return;if(recover)observed.value=actual;else value.value=actual}catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&([401,403].includes(cause.status)||!recover&&cause.status===404)){clear();denied.value=true}else error.value=errorMessage(cause)}}finally{if(current(s))busy.value=false}}
function open(){if(!writable.value||props.disabled||busy.value||review.value||!value.value)return;snapshot.value=value.value;draft.value=value.value.storedManualIccid??'';shown.value=true;error.value='';notice.value=''}
function cancel(){if(!busy.value){shown.value=false;snapshot.value=undefined;draft.value=''}}
async function save(remove=false){
 if(!writable.value||props.disabled||busy.value||review.value||!snapshot.value)return
 let chosen:IccidInformationIntent;try{chosen=prepareIccidInformation(projectId.value,props.deviceId,snapshot.value,remove?null:draft.value)}catch(cause){error.value=errorMessage(cause);return}
 intent.value=chosen;review.value='unknown';observed.value=undefined;shown.value=false;snapshot.value=undefined;busy.value=true;error.value='';const s=capture();controller=new AbortController();let accepted=false
 try{const returned=await props.transport.change(chosen,controller.signal);accepted=true;if(!current(s))return;if(!iccidInformationMatches(returned,chosen))throw new Error('ICCID保存回执与原选择不符');const actual=await props.transport.read(chosen.project,chosen.deviceId,controller.signal);if(!current(s))return;if(!iccidInformationMatches(actual,chosen))throw new Error('当前资料或类型已变化');value.value=actual;intent.value=undefined;review.value=undefined;draft.value='';notice.value=remove?'人工ICCID资料已清除。':'人工ICCID资料已保存并回读，仍为未核验标识。';emit('changed')}
 catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&(cause.status===401||accepted&&cause.status===403)){clear();denied.value=true;return}const rejected=!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&[400,403,404,409,413,422,429].includes(cause.status)&&cause.code!==10014;review.value=rejected?'rejected':'unknown';error.value=rejected?'本次保存被拒绝；读取当前资料后可重新编辑。':'原保存结果尚未核对；只读取当前资料，不会再次提交。'}}finally{if(current(s))busy.value=false}
}
function finish(){if(!review.value||busy.value||!observed.value)return;const unknown=review.value==='unknown';value.value=observed.value;observed.value=undefined;review.value=undefined;intent.value=undefined;draft.value='';error.value='';notice.value=unknown?'已采用当前资料；原保存结果仍未确认，未重新提交。':'已读取当前资料；被拒绝的保存未重试。'}
function reset(){clear();denied.value=false;if(readable.value)void load()}
watch([()=>projectId.value,()=>props.deviceId,()=>session.user?.accountId,()=>session.ready,()=>session.transitioning,()=>can('device:read'),()=>roles.includes(session.user?.projectRole||''),()=>roles.includes(currentProject.value?.myRole||'')],reset,{immediate:true,flush:'sync'});watch(writable,allowed=>{if(!allowed&&!review.value)cancel()},{flush:'sync'});watch(locked,v=>emit('locked',v),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;clear();dispose();emit('locked',false)})
</script>
<template><section v-if="!reference||!readable||error||notice||review||shown||value&&(value.source!=='DISABLED'||value.storedManualIccid!==null)" class="iccid-information" :class="{'information-standard':reference}"><header><h3>ICCID资料（未核验）</h3><el-button v-if="!reference&&writable&&value&&(value.source==='MANUAL'||value.storedManualIccid!==null)" size="small" :disabled="disabled||locked" @click="open">编辑ICCID资料</el-button></header><p>仅保存设备标识，保留前导零；尚未核验实体卡，不代表运营商关联、卡状态或用量。</p><p v-if="!readable">当前账号没有读取权限。</p><template v-else><template v-if="value"><p class="information-value" :class="{'is-unset':reference&&value.effectiveIccid===null}">{{reference?(value.effectiveIccid??'未设置'):`当前有效ICCID：${value.effectiveIccid??'—'}`}}</p><p v-if="value.source==='DISABLED'">当前类型已关闭ICCID资料；{{value.storedManualIccid===null?'没有保留人工资料。':'原人工资料仍保留，可显式清除。'}}</p><p v-else-if="value.source==='UNAVAILABLE'">当前类型或报告来源不合格，没有有效标识，不回退人工资料。</p><p v-else-if="value.source==='MANUAL'">来源：人工未核验资料</p><p v-else-if="value.reported">来源：设备上报 {{value.reported.propertyKey}} · 固定模型 {{value.reported.modelVersionId}} · 上报版本 {{value.reported.reportedRevision}} · 发生时间 {{value.reported.occurredAt}}</p><p v-if="value.storedManualIccid!==null&&value.source!=='MANUAL'">保留人工ICCID：{{value.storedManualIccid}}</p><p v-if="!reference" class="tl-muted">人工资料版本 {{value.informationVersion}}</p></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><template v-if="review"><p>{{review==='unknown'?'原保存结果尚未确认':'本次保存已被拒绝'}}。原请求键：{{intent?.key}}；当前同值不能证明原请求结果。</p><p v-if="observed">当前人工资料 {{observed.storedManualIccid??'—'}}，版本 {{observed.informationVersion}}</p><el-button :loading="busy" @click="load(true)">读取当前ICCID资料核对</el-button><el-button :disabled="busy||!observed" @click="finish">采用当前资料并结束核对</el-button></template><template v-else><div class="information-standard-actions"><el-button v-if="reference&&writable&&value&&(value.source==='MANUAL'||value.storedManualIccid!==null)" size="small" :disabled="disabled||locked||!value" @click="open">编辑</el-button><el-button v-if="!reference" size="small" :loading="busy" :disabled="busy||shown" @click="load()">刷新ICCID资料</el-button></div></template></template>
<el-dialog :model-value="shown&&readable&&writable" title="编辑未核验ICCID资料" width="min(560px,94vw)" :close-on-click-modal="false" @close="cancel"><el-form label-position="top"><el-form-item label="ICCID数字原文"><el-input v-model="draft" aria-label="ICCID数字原文" inputmode="numeric" maxlength="32" :disabled="busy||snapshot?.source!=='MANUAL'"/></el-form-item></el-form><p>1至32位数字为本平台技术预算，不自动删空格、去前导零或转换填充字符。关闭或上报来源只允许清除保留的人工资料。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="cancel">取消</el-button><el-button :disabled="disabled||!writable||busy||!snapshot||snapshot.storedManualIccid===null" @click="save(true)">清除人工ICCID</el-button><el-button type="primary" :disabled="disabled||!writable||busy||snapshot?.source!=='MANUAL'" @click="save()">保存ICCID资料</el-button></template></el-dialog></section></template>
<style scoped>.information-standard-actions{display:flex;gap:10px;margin-top:8px}.information-standard-actions .el-button+.el-button{margin-left:0}.iccid-information header{display:flex;align-items:center;justify-content:space-between;gap:12px}.iccid-information p{font-size:13px;line-height:1.7;overflow-wrap:anywhere}</style>
